USERS = {"aziz": "user", "admin": "admin"}
DOCS = {1: {"владелец": "aziz", "текст": "мой документ"}}

def can_read(user, doc_id):
    doc = DOCS.get(doc_id)
    if doc is None:
        return False
    if USERS.get(user) == "admin":
        return True
    return doc["владелец"] == user

for user in ("aziz", "admin", "chuzhoy"):
    print(f"{user:9} -> документ 1: {can_read(user, 1)}, документ 42: {can_read(user, 42)}")

def safe_next(path):
    if not path:
        return "/"
    # только внутренний путь: одна ведущая косая и без схемы
    if path.startswith("//") or "://" in path or path.startswith("\\\\"):
        return "/"
    if not path.startswith("/"):
        return "/"
    return path

for candidate in ["/profile", "/orders/5", "https://zlo.example/fake",
                  "//zlo.example/fake", "javascript:alert(1)", "", None]:
    print(f"{str(candidate):28} -> {safe_next(candidate)}")

