def to_tuple(version):
    return tuple(int(part) for part in version.split("."))

installed = "1.0.9"
fixed_in = "1.0.10"

print("как строки:", installed < fixed_in)
print("как числа: ", to_tuple(installed) < to_tuple(fixed_in))

LIMIT = 3
attempts = {}

def try_login(user, password):
    if attempts.get(user, 0) >= LIMIT:
        return "заблокировано"
    if password == "correct-horse":
        attempts[user] = 0
        return "вход выполнен"
    attempts[user] = attempts.get(user, 0) + 1
    return "неверный пароль"

for guess in ["1234", "qwerty", "admin", "correct-horse"]:
    print(guess, "->", try_login("aziz", guess))

SECRET_FIELDS = {"password", "token", "api_key", "card"}

